<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Transkrip <?= esc($profile['nim']) ?></title><link href="<?= base_url('assets/css/bootstrap.min.css') ?>" rel="stylesheet"><link href="<?= base_url('assets/css/siakad.css') ?>" rel="stylesheet"></head><body class="print-page"><main class="container print-sheet"><div class="d-flex justify-content-between align-items-start mb-4"><div><div class="eyebrow">Dokumen akademik</div><h1>Transkrip Nilai</h1><p class="mb-0">Rekapitulasi hasil studi</p></div><button class="btn btn-primary no-print" onclick="window.print()">Cetak</button></div><div class="print-profile"><div><span>Nama</span><strong><?= esc($profile['name']) ?></strong></div><div><span>NIM</span><strong><?= esc($profile['nim']) ?></strong></div><div><span>Program studi</span><strong><?= esc($profile['prodi_name']) ?></strong></div></div><?php $points=['A'=>4.0,'A-'=>3.7,'B+'=>3.3,'B'=>3.0,'B-'=>2.7,'C+'=>2.3,'C'=>2.0,'D'=>1.0,'E'=>0.0]; $sum=0;$sks=0; foreach($grades as $g){$sum+=($points[$g['nilai_huruf']]??0)*(int)$g['sks'];$sks+=(int)$g['sks'];} ?><table class="table data-table mt-4"><thead><tr><th>No.</th><th>Kode</th><th>Mata kuliah</th><th>Semester</th><th>SKS</th><th>Nilai</th></tr></thead><tbody><?php foreach ($grades as $i => $row): ?><tr><td><?= $i + 1 ?></td><td><?= esc($row['kode']) ?></td><td><?= esc($row['mata_kuliah']) ?></td><td><?= esc($row['semester']) ?> <?= esc($row['tahun_ajaran']) ?></td><td><?= (int) $row['sks'] ?></td><td><?= esc($row['nilai_huruf']) ?> <span class="text-muted">(<?= number_format((float) $row['nilai_angka'], 2) ?>)</span></td></tr><?php endforeach ?></tbody></table><div class="transcript-total"><span>Total SKS dinilai <strong><?= $sks ?></strong></span><span>IPK <strong><?= $sks ? number_format($sum / $sks, 2) : '—' ?></strong></span></div></main></body></html>
